// On-device text triage. A line-by-line port of scripts/text_triage.py (Swahili / Sheng / English rule engine, no classifier).
// The rules live in assets/text_triage_rules.json (generated by `py scripts\export_text_rules.py`). Same message -> same answer as the server.
// Never throws: the worst case is "unclear, ask the resident".
import 'dart:convert';

import 'package:flutter/services.dart' show AssetBundle, rootBundle;

/// What the engine understood. The resident ALWAYS confirms it.
class TextTriageResult {
  const TextTriageResult({
    this.category,
    this.subtype,
    this.subtypeConfidence = 'low',
    this.method = 'unclear',
    this.confidence = 'low',
    this.flags = const [],
    this.possibleFlags = const [],
    this.priorityFloor = 'Low',
    this.needsClarification = true,
    this.alternatives = const [],
    this.safetyCheck = false,
    this.themes = const [],
  });

  final String? category;
  final String? subtype;
  final String subtypeConfidence;
  final String method; // lexicon | ambiguous | unclear | safety_flag | empty | error
  final String confidence; // high | low
  final List<String> flags;
  final List<String> possibleFlags;
  final String priorityFloor;
  final bool needsClarification;
  final List<String> alternatives;
  final bool safetyCheck;
  final List<String> themes;
}

class _Term {
  _Term(this.key, String pattern) : rx = RegExp(pattern);
  final String key;
  final RegExp rx;

  List<List<int>> spans(String s) => [
    for (final m in rx.allMatches(s)) [m.start, m.end],
  ];
}

class _Pair {
  _Pair(this.who, this.act, this.window);
  final List<_Term> who;
  final List<_Term> act;
  final int window;

  List<List<int>> find(String s) {
    final wh = <List<int>>[for (final x in who) ...x.spans(s)];
    final ac = <List<int>>[for (final x in act) ...x.spans(s)];
    final found = <List<int>>[];
    for (final w in wh) {
      for (final a in ac) {
        final String gap;
        if (w[1] <= a[0]) {
          gap = s.substring(w[1], a[0]);
        } else if (a[1] <= w[0]) {
          gap = s.substring(a[1], w[0]);
        } else {
          continue; // overlapping words are not a couple
        }
        final words = gap.split(' ').where((x) => x.isNotEmpty).length;
        if (words <= window) {
          found.add([w[0] < a[0] ? w[0] : a[0], w[1] > a[1] ? w[1] : a[1]]);
        }
      }
    }
    return found;
  }
}

class _Hit {
  const _Hit(this.start, this.end, this.label, this.tier);
  final int start;
  final int end;
  final String label;
  final String tier; // strong | weak
}

class _Group {
  _Group(this.strong, this.strongPairs, this.weak, this.weakPairs);
  final List<_Term> strong;
  final List<_Pair> strongPairs;
  final List<_Term> weak;
  final List<_Pair> weakPairs;
}

class TextTriageEngine {
  TextTriageEngine._(Map<String, dynamic> rules)
    : _flagOrder = _strings(rules['constants']['flagOrder']),
      _flagTarget = {
        for (final e in (rules['constants']['flagTarget'] as Map).entries)
          e.key as String: _strings(e.value),
      },
      _maxChips = rules['constants']['maxChips'] as int,
      _maxTextChars = rules['constants']['maxTextChars'] as int,
      _incident = _strings(rules['constants']['incident']),
      _snapNever = _strings(rules['constants']['snapNever']).toSet(),
      _cats = _strings(rules['categoryOrder']),
      _ignore = _terms(rules['ignore']),
      _known = _strings(rules['knownTokens']).toSet(),
      _snap = {
        for (final e in (rules['snapVocab'] as Map).entries)
          e.key as String: e.value as String,
      },
      _flags = {
        for (final e in (rules['flags'] as Map).entries)
          e.key as String: _group(e.value as Map, 'strong', 'pairs', 'weak', 'weakPairs'),
      },
      _categories = {
        for (final e in (rules['categories'] as Map).entries)
          e.key as String: _group(e.value as Map, 'strong', 'strongPairs', 'weak', 'weakPairs'),
      },
      _subtypes = {
        for (final c in (rules['categories'] as Map).entries)
          c.key as String: {
            for (final s in ((c.value as Map)['subtypes'] as Map).entries)
              s.key as String: _group(s.value as Map, 'strong', 'strongPairs', 'weak', 'weakPairs'),
          },
      },
      _themes = {
        for (final e in (rules['themes'] as Map).entries) e.key as String: _terms(e.value),
      };

  /// Loads the rules shipped inside the app (assets/text_triage_rules.json).
  static Future<TextTriageEngine> loadFromAsset({
    AssetBundle? bundle,
    String path = 'assets/text_triage_rules.json',
  }) async => TextTriageEngine.fromJsonString(await (bundle ?? rootBundle).loadString(path));

  factory TextTriageEngine.fromJsonString(String source) =>
      TextTriageEngine._(jsonDecode(source) as Map<String, dynamic>);

  final List<String> _flagOrder;
  final Map<String, List<String>> _flagTarget;
  final int _maxChips;
  final int _maxTextChars;
  final List<String> _incident;
  final Set<String> _snapNever;
  final List<String> _cats;
  final List<_Term> _ignore;
  final Set<String> _known;
  final Map<String, String> _snap;
  final Map<String, _Group> _flags;
  final Map<String, _Group> _categories;
  final Map<String, Map<String, _Group>> _subtypes;
  final Map<String, List<_Term>> _themes;

  static const _medical = 'Medical Emergency';
  static const _other = 'Other / General';

  // ---------------------------------------------------------------- loading helpers
  static List<String> _strings(Object? v) => [for (final x in (v as List)) x as String];

  static List<_Term> _terms(Object? v) => [
    for (final x in (v as List)) _Term((x as Map)['k'] as String, x['r'] as String),
  ];

  static List<_Pair> _pairs(Object? v) => [
    for (final x in (v as List))
      _Pair(_terms((x as Map)['who']), _terms(x['act']), x['w'] as int),
  ];

  static _Group _group(Map m, String s, String sp, String w, String wp) =>
      _Group(_terms(m[s]), _pairs(m[sp]), _terms(m[w]), _pairs(m[wp]));

  // ---------------------------------------------------------------- text preparation
  static String _normalize(String s) {
    final lower = s.toLowerCase().replaceAll('’', "'");
    return lower.replaceAll(RegExp(r"[^a-z0-9' ]+"), ' ').replaceAll(RegExp(r'\s+'), ' ').trim();
  }

  /// "moooto" -> "moto"; SMS "nmeibiwa" -> "nimeibiwa".
  static String _canonical(String s) {
    final a = s.replaceAllMapped(RegExp(r'(.)\1{2,}'), (m) => m[1]!);
    return a.replaceAllMapped(RegExp(r'\bn([mltk])(?=[aeiou])'), (m) => 'ni${m[1]}');
  }

  String _maskIdioms(String input) {
    var s = input;
    for (final tm in _ignore) {
      for (final sp in tm.spans(s)) {
        s = s.substring(0, sp[0]) + ' ' * (sp[1] - sp[0]) + s.substring(sp[1]);
      }
    }
    return s;
  }

  static bool _oneSlip(String tok, String word) {
    if (tok.length == word.length - 1) {
      for (var i = 0; i < word.length; i++) {
        if (word.substring(0, i) + word.substring(i + 1) == tok) return true;
      }
      return false;
    }
    if (tok.length == word.length && tok != word) {
      final d = <int>[for (var i = 0; i < word.length; i++) if (tok[i] != word[i]) i];
      return d.length == 2 &&
          d[1] == d[0] + 1 &&
          tok[d[0]] == word[d[1]] &&
          tok[d[1]] == word[d[0]];
    }
    return false;
  }

  /// Typo tolerance for SAFETY FLAGS only ("suicde", "molestd").
  String _snapFlagTypos(String s) {
    final out = <String>[];
    for (var tok in s.split(' ').where((w) => w.isNotEmpty)) {
      if (tok.length >= 6 &&
          !_known.contains(tok) &&
          !_snap.containsKey(tok) &&
          !_snapNever.contains(tok)) {
        final cands = _snap.keys.where((v) => v[0] == tok[0] && _oneSlip(tok, v)).toList();
        if (cands.isNotEmpty && cands.map((c) => _snap[c]).toSet().length == 1) {
          cands.sort();
          tok = cands.first;
        }
      }
      out.add(tok);
    }
    return out.join(' ');
  }

  // ---------------------------------------------------------------- matching
  List<_Hit> _hits(List<_Term> terms, List<_Pair> pairs, String s, String label, String tier) {
    final out = <_Hit>[];
    for (final tm in terms) {
      for (final sp in tm.spans(s)) {
        out.add(_Hit(sp[0], sp[1], label, tier));
      }
    }
    for (final p in pairs) {
      for (final sp in p.find(s)) {
        out.add(_Hit(sp[0], sp[1], label, tier));
      }
    }
    return out;
  }

  /// Longest span wins: a hit strictly inside a longer hit is dropped ("maji ya moto" removes "moto").
  List<_Hit> _dropInsideLonger(List<_Hit> hits) {
    final keep = <_Hit>[];
    for (final h in hits) {
      final inside = hits.any(
        (o) =>
            !identical(o, h) &&
            o.start <= h.start &&
            o.end >= h.end &&
            (o.end - o.start) > (h.end - h.start),
      );
      if (!inside) keep.add(h);
    }
    final uniq = <_Hit>[];
    final seen = <String>{};
    for (final h in keep) {
      if (seen.add('${h.start},${h.end},${h.label},${h.tier}')) uniq.add(h);
    }
    return uniq;
  }

  /// Returns [flags, possibleFlags].
  List<List<String>> _lexiconFlags(String s) {
    final flags = <String>[];
    final possible = <String>[];
    final names = [..._flagOrder, ..._flags.keys.where((k) => !_flagOrder.contains(k))];
    for (final name in names) {
      final f = _flags[name];
      if (f == null) continue;
      final st = _hits(f.strong, f.strongPairs, s, name, 'strong');
      final wk = _hits(f.weak, f.weakPairs, s, name, 'weak');
      if (st.isNotEmpty) {
        flags.add(name);
      } else if (wk.isNotEmpty) {
        possible.add(name);
      }
    }
    return [flags, possible];
  }

  /// Returns [strongVotes, weakHits].
  List<Map<String, int>> _lexiconVotes(String s) {
    var all = <_Hit>[];
    for (final c in _cats) {
      final v = _categories[c]!;
      all = [
        ...all,
        ..._hits(v.strong, v.strongPairs, s, c, 'strong'),
        ..._hits(v.weak, v.weakPairs, s, c, 'weak'),
      ];
    }
    final kept = _dropInsideLonger(all);
    final strong = <String, int>{for (final c in _cats) c: 0};
    final weak = <String, int>{};
    for (final h in kept) {
      if (h.tier == 'strong') {
        strong[h.label] = strong[h.label]! + 1;
      } else {
        weak[h.label] = (weak[h.label] ?? 0) + 1;
      }
    }
    // An INCIDENT beats a BODY PROBLEM when both are named (crash + bleeding = Road Accident).
    if (strong[_medical]! > 0 && _incident.any((c) => strong[c]! > 0)) {
      weak[_medical] = (weak[_medical] ?? 0) + strong[_medical]!;
      strong[_medical] = 0;
    }
    // "Other / General" is the fallback: any specific category wins.
    if (strong[_other]! > 0 && _cats.any((c) => c != _other && strong[c]! > 0)) {
      weak[_other] = (weak[_other] ?? 0) + strong[_other]!;
      strong[_other] = 0;
    }
    return [strong, weak];
  }

  /// Returns [subtype or null, confidence].
  List<String?> _subtypeFor(String category, String s) {
    final subs = _subtypes[category]!;
    final scores = <String, int>{};
    for (final e in subs.entries) {
      final h = _dropInsideLonger(_hits(e.value.strong, e.value.strongPairs, s, e.key, 'strong'));
      if (h.isNotEmpty) scores[e.key] = h.length;
    }
    if (scores.isNotEmpty) {
      final top = scores.values.reduce((a, b) => a > b ? a : b);
      final best = scores.entries.where((e) => e.value == top).map((e) => e.key).toList();
      return best.length == 1 ? [best.first, 'high'] : [null, 'low'];
    }
    final weakScores = <String>[
      for (final e in subs.entries)
        if (_hits(e.value.weak, e.value.weakPairs, s, e.key, 'weak').isNotEmpty) e.key,
    ];
    return weakScores.length == 1 ? [weakScores.first, 'low'] : [null, 'low'];
  }

  List<String> _themesFor(String s) => [
    for (final e in _themes.entries)
      if (e.value.any((tm) => tm.spans(s).isNotEmpty)) e.key,
  ];

  // ---------------------------------------------------------------- public API
  TextTriageResult triage(String text) {
    try {
      if (text.trim().isEmpty) return const TextTriageResult(method: 'empty');
      final cut = text.length > _maxTextChars ? text.substring(0, _maxTextChars) : text;
      final s = _maskIdioms(_canonical(_normalize(cut)));
      final fp = _lexiconFlags(_snapFlagTypos(s));
      final flags = fp[0];
      final possible0 = fp[1];
      for (final fl in _flagOrder) {
        if (flags.contains(fl)) {
          final target = _flagTarget[fl]!; // [category, subtype, floor]
          return TextTriageResult(
            category: target[0],
            subtype: target[1],
            subtypeConfidence: 'high',
            method: 'safety_flag',
            confidence: 'high',
            flags: flags,
            possibleFlags: possible0,
            priorityFloor: target[2],
            needsClarification: false,
            safetyCheck: true,
          );
        }
      }
      final votes = _lexiconVotes(s);
      final strong = votes[0];
      final weak = votes[1];
      final topV = _cats.map((c) => strong[c]!).reduce((a, b) => a > b ? a : b);
      final lexTop = _cats.where((c) => strong[c] == topV && strong[c]! > 0).toList();
      String? cat;
      var method = 'unclear';
      var conf = 'low';
      if (lexTop.length == 1) {
        cat = lexTop.first;
        method = 'lexicon';
        conf = 'high';
      } else if (lexTop.length > 1) {
        method = 'ambiguous'; // mixed strong signals: do not guess, ask the resident
      }
      final order = <String, int>{for (var i = 0; i < _cats.length; i++) _cats[i]: i};
      final evidence = _cats.where((c) => strong[c]! > 0 || (weak[c] ?? 0) > 0).toList()
        ..sort((a, b) {
          final byStrong = strong[b]! - strong[a]!;
          if (byStrong != 0) return byStrong;
          final byWeak = (weak[b] ?? 0) - (weak[a] ?? 0);
          if (byWeak != 0) return byWeak;
          return order[a]! - order[b]!;
        });
      final alts = evidence.where((c) => c != cat).take(_maxChips).toList();
      final sub = cat != null ? _subtypeFor(cat, s) : <String?>[null, 'low'];
      final possible = possible0.where((f) => f == 'self_harm' || cat == null).toList();
      final themes = sub[0] == 'emotional_distress' ? _themesFor(s) : <String>[];
      return TextTriageResult(
        category: cat,
        subtype: sub[0],
        subtypeConfidence: sub[1] ?? 'low',
        method: method,
        confidence: conf,
        flags: flags,
        possibleFlags: possible,
        needsClarification: cat == null,
        alternatives: alts,
        safetyCheck: sub[0] == 'emotional_distress' || possible.contains('self_harm'),
        themes: themes,
      );
    } catch (_) {
      return const TextTriageResult(method: 'error');
    }
  }
}
